public static int computeIterative(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int index = 0;
    int n = s.length();

    // Skip leading whitespace
    while (index < n && s.charAt(index) == ' ') {
        index++;
    }

    if (index == n) {
        return 0;
    }

    // Check sign
    int sign = 1;
    if (s.charAt(index) == '+' || s.charAt(index) == '-') {
        sign = s.charAt(index) == '-' ? -1 : 1;
        index++;
    }

    // Convert digits
    int result = 0;
    while (index < n && Character.isDigit(s.charAt(index))) {
        int digit = s.charAt(index) - '0';

        // Check for overflow
        if (result > Integer.MAX_VALUE / 10
                || (result == Integer.MAX_VALUE / 10 && digit > Integer.MAX_VALUE % 10)) {
            return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        }

        result = result * 10 + digit;
        index++;
    }

    return sign * result;
}

public static int computeWithStringBuilder(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    s = s.trim();
    if (s.length() == 0) {
        return 0;
    }

    StringBuilder sb = new StringBuilder();
    int sign = 1;
    int start = 0;

    if (s.charAt(0) == '+' || s.charAt(0) == '-') {
        sign = s.charAt(0) == '-' ? -1 : 1;
        start = 1;
    }

    for (int i = start; i < s.length() && Character.isDigit(s.charAt(i)); i++) {
        sb.append(s.charAt(i));
    }

    if (sb.length() == 0) {
        return 0;
    }

    try {
        long value = Long.parseLong(sb.toString()) * sign;
        if (value > Integer.MAX_VALUE) {
            return Integer.MAX_VALUE;
        }
        if (value < Integer.MIN_VALUE) {
            return Integer.MIN_VALUE;
        }
        return (int) value;
    } catch (NumberFormatException e) {
        return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
    }
}

public static int computeWithRecursion(String s) {
    s = s.trim();
    if (s.length() == 0) {
        return 0;
    }

    int[] index = { 0 };
    int sign = parseSign(s, index);
    return sign * parseDigits(s, index, 0);
}
